async function api(action,body={}){
  if(TOUR_MODE)return tourData.request(action,body);
  if(DEMO&&action==='drive_status')return {configured:false,connected:false,email:''};
  if(DEMO)return demoRequest(action,body);
  const get=getActions.has(action),params=new URLSearchParams({action});if(get)for(const [k,v]of Object.entries(body))if(v!=null)params.set(k,v);
  const headers=accountActions.has(action)||['switch_studio','create_studio'].includes(action)?{}:resourceHeaders();const requestIteration=body instanceof FormData?body.get('iteration'):body.iteration;if(state.client&&requestIteration){const share=state.data?.communication?.iterations?.find(i=>i.id===requestIteration)?.share_id;if(share)headers.Authorization='Client '+share;}if(state.csrf&&!get)headers['X-CSRF-Token']=state.csrf;
  const opts={method:get?'GET':'POST',credentials:'same-origin',headers};if(!get){if(body instanceof FormData)opts.body=body;else{headers['Content-Type']='application/json';opts.body=JSON.stringify(body);}}
  let response;
  try{response=await fetch('api.php?'+params,opts);}catch(e){console.error('[Studiodeck API] Network request failed',{action,method:opts.method,message:e.message});throw e;}
  let result;
  try{result=await response.json();}catch{console.error('[Studiodeck API] Invalid JSON response',{action,method:opts.method,status:response.status,contentType:response.headers.get('content-type')});throw Error(tr('error_the_studio_server_is_unavailable_please_check_that_the_php_application_is_running'));}
  if(!response.ok){
    console.error('[Studiodeck API] Request failed',{action,method:opts.method,status:response.status,error:result.error,details:result.debug});
    if(!state.client&&result.project_access)setTimeout(()=>projectAccess.gate(result.project_access,'reactivate').catch(e=>toast(e.message)),0);else if(action==='create_project'&&response.status===402)setTimeout(()=>projectAccess.gate().catch(e=>toast(e.message)),0);
    throw Object.assign(Error(translateError(result.error||'This request could not be completed.')),{status:response.status});
  }
  return result;
}
