const hydratingImages=new Set();
let scrollImageObserver;
async function hydrateImages(nearby=false){if(DEMO)return;const d=state.data;if(!d)return;
    if(!nearby){scrollImageObserver?.disconnect();scrollImageObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.dataset.imageReady='1';scrollImageObserver.unobserve(entry.target);}hydrateImages(true);},{rootMargin:'800px'});}
    for(const placeholder of document.querySelectorAll('[data-image]')){
        if(!placeholder.isConnected)continue;
        if(placeholder.closest('.presentation-scroll')&&!placeholder.dataset.imageReady){if(!nearby)scrollImageObserver.observe(placeholder);continue;}
        const key=placeholder.dataset.image;if(hydratingImages.has(key))continue;
        const p=new URLSearchParams({action:placeholder.dataset.slide&&!placeholder.dataset.slide.startsWith('legacy-')?'slide_image':placeholder.dataset.page?'document_page':'file',id:placeholder.dataset.version,iteration:d.iteration.id,preview:1});
        if(placeholder.dataset.slide)p.set('slide_id',placeholder.dataset.slide);if(placeholder.dataset.original==='1')p.set('original','1');else if(placeholder.dataset.variant)p.set('image_version_id',placeholder.dataset.variant);
        if(placeholder.dataset.page)p.set('page',placeholder.dataset.page);if(placeholder.dataset.crop)p.set('image',placeholder.dataset.crop);
        hydratingImages.add(key);
        try{let url=imageCache.get(key);if(!url){const r=await fetch('api.php?'+p,{credentials:'same-origin',headers:resourceHeaders()});if(!r.ok)continue;url=URL.createObjectURL(await r.blob());const decoded=new Image();decoded.src=url;await decoded.decode();imageCache.set(key,url);}
            document.querySelectorAll(`[data-image="${CSS.escape(key)}"]`).forEach(el=>{const im=document.createElement('img');im.src=url;im.alt=el.dataset.alt;im.loading='lazy';im.className=el.className.replace('image-pending','');im.style.cssText=el.style.cssText;el.replaceWith(im);});
        }catch{}finally{hydratingImages.delete(key);}
    }
}
async function prepareGeneratedImages(previous,updated){
    const old=new Map((previous?.slides||[]).map(s=>[s.id,s.image_version_id]));
    for(const slide of updated.slides||[]){
        if(!slide.image_version_id||old.get(slide.id)===slide.image_version_id)continue;
        selectedEnhancements.delete(slide.id);
        for(const original of [false,true]){
            const f={id:slide.source_version_id,page_number:slide.page_number,image_number:slide.image_number,slide_image_version:original?'':slide.image_version_id,show_original:original},key=imageKey(f);
            if(imageCache.has(key)||DEMO)continue;
            const params=new URLSearchParams({action:'slide_image',iteration:updated.iteration.id,slide_id:slide.id});if(original)params.set('original','1');else params.set('image_version_id',slide.image_version_id);
            try{const response=await fetch('api.php?'+params,{credentials:'same-origin',headers:resourceHeaders()});if(!response.ok)continue;const url=URL.createObjectURL(await response.blob()),im=new Image();im.src=url;await im.decode();imageCache.set(key,url);}catch{}
        }
    }
}
async function openProject(pid,iid=null,preview=false,bypass=false,options={}){if(!DEMO&&!bypass&&!await projectAccess.gate(pid,'open',{iteration:iid,preview,...options}))return false;state.activityPage=0;state.slideGroup='';state.present=false;state.inspectHidden=false;state.client=false;state.shareToken='';state.clientShareId='';state.accountClientProject='';state.data=await api('project',{id:pid,iteration:iid});state.slide=0;state.imageIndex=0;state.chat=[];if(preview)startPresentation();if(!options.deferRender){if(!state.present)render();pollJobs();}return true;}
async function refresh(force=false){if(!state.data)return;const scroll=window.scrollY;const previous=JSON.stringify(state.data),updated=await api(state.client?'deck':'project',state.client?{}:{id:state.data.project.id,iteration:state.data.iteration.id,events_page:state.tab==='activity'?(state.activityPage||0):0});if(!force&&(document.activeElement?.closest('#comm-reply-form')||document.querySelector('[data-uploading]')||budgetChoiceSaving.size||state.reordering||document.activeElement?.matches('[data-budget-range]')||document.activeElement?.closest('[data-form="inline-slide-labels"]'))){pollJobs();return;}const accessExpired=!state.client&&state.data.billing?.active&&updated.billing&&!updated.billing.active;await prepareGeneratedImages(state.data,updated);if(updated.slides?.some(s=>s.metadata?.motion_candidate?.media_id&&s.metadata.motion_candidate.media_id!==state.data.slides?.find(old=>old.id===s.id)?.metadata?.motion_candidate?.media_id))toast(tr('media_ready'));state.data=updated;updateEnhancementAllowance();if(JSON.stringify(updated)!==previous){render();renderProcessing();if(magnifiedPhoto)renderPhotoLightbox();}window.scrollTo(0,scroll);pollJobs();if(accessExpired){state.present=false;render();await projectAccess.gate(updated.project.id);}}
function pollJobs(){clearTimeout(state.poll);if(state.tab==='projects'&&!state.present){if(state.projects.some(p=>p.processing))state.poll=setTimeout(async()=>{try{await loadProjects();const grid=$('#project-grid');if(grid){grid.innerHTML=projectTiles();hydrateProjectCovers();}}catch(error){toast(error.message);}pollJobs();},2200);return;}if(pending())state.poll=setTimeout(()=> (state.reordering?Promise.resolve():refresh()).catch(e=>{toast(e.message);pollJobs();}),1800);}
function slideDefs(){syncLanguage();return presentationSlides(state.data,{includeHidden:!!state.inspectHidden});}
function slideFiles(id){const def=slideDefs().find(s=>s.id===id);id=def?.systemType||id;if(id==='summary'||id==='intro')return state.data.files;if(id==='changes')return state.data.files.filter(f=>f.number>1);if(def?.visual)return state.data.files.filter(f=>f.id===def.visual.id);return state.data.files.filter(f=>f.category===id);}
function resourceHeaders(){if(state.clientShareId)return {Authorization:'Client '+state.clientShareId};return state.studio?.id?{'X-Studio-ID':state.studio.id}:{};}
async function showDestinations(autoOpen=false){
    if(DEMO){await loadProjects();state.tab='projects';state.present=false;render();return;}
    if(activeModal)closeModal();if(magnifiedPhoto)closePhotoLightbox(false);clearTimeout(state.poll);
    state.client=false;state.present=false;state.shareToken='';state.clientShareId='';state.accountClientProject='';state.data=null;state.profile=null;state.inspectHidden=false;
    const data=await api('destinations');state.destinations=data;
    if(autoOpen&&data.studios.length+data.projects.length===1&&!data.conversations?.length){if(data.studios.length)return openDestinationStudio(data.studios[0].id);return openClientProject(data.projects[0].id);}
    state.tab='destinations';render();
}
async function openDestinationStudio(id,project=''){
    if(activeModal)closeModal();state.client=false;state.shareToken='';state.clientShareId='';state.accountClientProject='';
    applySession(await api('switch_studio',{studio_id:id}));await resetStudio();if(project){state.tab='overview';await openProject(project);}
}
async function openClientProject(project,iteration=null,slide=null,presentationMode=state.presentationMode){
    state.presentationMode=presentationMode;
    if(activeModal)closeModal();clearTimeout(state.poll);if(magnifiedPhoto)closePhotoLightbox(false);
    const selected=await api('client_project',{project_id:project,iteration});
    state.shareToken='';state.clientShareId=selected.share_id;state.accountClientProject=selected.project_id;state.client=true;state.present=true;state.inspectHidden=false;state.chat=[];state.imageIndex=0;state.profile=null;
    state.data=await api('deck');state.slide=Math.max(0,slideDefs().findIndex(s=>s.id===slide));render();if(state.presentationMode==='scroll')scrollToSlide(slideDefs()[state.slide]?.id,{smooth:false});else window.scrollTo(0,0);
    api('view_event',{iteration:state.data.iteration.id,slide:slideDefs()[state.slide]?.id||'intro'}).catch(()=>{});
}
function syncLanguage(){
 const project=state.present||state.client?state.data?.project:null;
 setLanguage(resolveLanguage({user:(state.client?state.data?.profile:state.user?.profile)?.language,project:project?.language,studio:project?.studio_language||state.studio?.language}));
 document.querySelector('.skip-link')?.replaceChildren(tr('skip_to_content'));
}
