function accountMenu(){openModal(tr("your_account"),`<div class="account-menu">${button(tr("your_profile"),'profile','','','users')}${state.user?`${button(tr("switch_workspace_project"),'destinations','','','grid')}${button(tr("log_out"),'logout','ghost','','logout')}`:button(tr("sign_in_to_see_all_your_projects"),'account-sign-in','primary','','arrow')}</div>`);}
function render(){if(!state.present)stopSlideMedia();state.routeFailed=false;syncLanguage();document.body.classList.toggle('presentation-reading',state.present&&state.presentationMode==='scroll');if(!state.present){stopScrollPresentation();scrollImageObserver?.disconnect();}if(!DEMO&&state.user&&state.tab!=='destinations'&&studioSetup.required()){document.body.classList.remove('presenting','website-editing');clearPresentationTheme();applyStudioTheme(state.studioTheme,true);$('#app').innerHTML=studioSetup.page();studioSetup.afterRender();syncWorkspaceUrl();return;}document.body.classList.toggle('website-editing',!!website.active());if(!website.active())website.destroyCode();if(!state.present&&isPresentationFullscreen())exitPresentationFullscreen().catch(e=>toast(e.message));document.body.classList.toggle('presenting',state.present&&(!!state.user||state.client));cancelSlideMotion();clearPresentationTheme();applyStudioTheme(state.studioTheme,!state.present&&!state.client);$('#overlay').style.cssText=state.client?'':studioThemeStyle(state.studioTheme);if(!state.present)state.inspectHidden=false;if(!state.user&&!state.client){renderLogin();return;}if(state.tab==='destinations'&&!state.present){$('#app').innerHTML=destinationPage(state.destinations,defaultBrand());syncPresentationNavigation();syncBudgetLayout();syncWorkspaceUrl();return;}if(state.client&&state.communicationOpen&&communication.enabled()){$('#app').innerHTML=communication.clientPage();communication.afterRender();return;}if(website.active()){const trialBar=DEMO?'':billing.trialBar();$('#app').innerHTML=`<div class="${trialBar?'billing-bar-layout':''}">${trialBar}${website.page()}</div>`;website.afterRender();syncWorkspaceUrl();return;}if(state.present){renderPresentation();communication.afterRender();syncWorkspaceUrl();return;}renderWorkspace();syncPresentationNavigation();syncBudgetLayout();hydrateImages();hydrateProjectCovers();hydrateCommentPreviews();communication.afterRender();syncWorkspaceUrl();}

function sidebar(){return `<aside class="sidebar"><button data-action="projects" aria-label="${tr("studio_your_projects")}">${brand()}</button><div class="studio-switch" title="${esc(state.studio?.name||tr("studio_current_studio"))}"><span class="studio-mark">${esc(initials(state.studio?.name||tr("studio_studio")))}</span><select id="studio-select" aria-label="${tr("studio_current_studio")}">${(state.studios||[{id:'demo',get name(){return tr("studio_your_design_studio");}}]).map(s=>`<option value="${esc(s.id)}" ${s.id===state.studio?.id?'selected':''}>${esc(s.name)}</option>`).join('')}${!DEMO?`<option value="new-studio">＋ ${esc(tr('studio_create_new_environment'))}</option>`:''}</select></div><p class="sidebar-caption">${tr("studio_workspace")}</p><button aria-label="${esc(tr("studio_all_projects",{v4:''}))}" title="${esc(tr("studio_all_projects",{v4:''}))}" class="side-link ${state.tab==='projects'?'active':''}" data-action="projects">${icon('grid')}<span class="side-link-label">${esc(tr("studio_all_projects",{v4:''}))}</span></button><button aria-label="${esc(tr("studio_current_project",{v7:''}))}" title="${esc(tr("studio_current_project",{v7:''}))}" class="side-link ${state.data?.project&&!['projects','studio-users','all-activity','all-comments','profile','billing','website'].includes(state.tab)?'active':''}" data-action="tab" data-tab="overview" ${state.data?.project?'':'disabled'}>${icon('folder')}<span class="side-link-label">${esc(tr("studio_current_project",{v7:''}))}</span></button><button aria-label="${esc(tr("studio_activity",{v9:''}))}" title="${esc(tr("studio_activity",{v9:''}))}" class="side-link ${state.tab==='all-activity'?'active':''}" data-action="all-activity">${icon('activity')}<span class="side-link-label">${esc(tr("studio_activity",{v9:''}))}</span></button><button aria-label="${esc((DEMO?tr("studio_comments",{v11:''}):communication.t('Communication')))}" title="${esc((DEMO?tr("studio_comments",{v11:''}):communication.t('Communication')))}" class="side-link ${state.tab==='all-comments'?'active':''}" data-action="all-comments">${icon('chat')}<span class="side-link-label">${esc((DEMO?tr("studio_comments",{v11:''}):communication.t('Communication')))}</span> <span class="unread-total">${state.unreadCount?tr("studio_unread",{v0:state.unreadCount}):''}</span></button>${!DEMO&&state.studio?.role==='admin'?`<button class="side-link ${state.tab==='website'?'active':''}" data-action="website" title="Website" aria-label="Website">${icon('compass')}<span class="side-link-label">Website</span></button>`:''}<div class="sidebar-bottom">${!DEMO&&state.studio?.role==='admin'?`<button aria-label="${esc(tr("studio_billing",{v1:''}))}" title="${esc(tr("studio_billing",{v1:''}))}" class="side-link ${state.tab==='billing'?'active':''}" data-action="billing">${icon('budget')}<span class="side-link-label">${esc(tr("studio_billing",{v1:''}))}</span></button>`:''}<button aria-label="${esc(tr("studio_studio_users",{v14:''}))}" title="${esc(tr("studio_studio_users",{v14:''}))}" class="side-link ${state.tab==='studio-users'?'active':''}" data-action="studio-users">${icon('users')}<span class="side-link-label">${esc(tr("studio_studio_users",{v14:''}))}</span></button><button aria-label="${esc(tr("studio_studio_settings",{v16:''}))}" title="${esc(tr("studio_studio_settings",{v16:''}))}" class="side-link" data-action="settings">${icon('settings')}<span class="side-link-label">${esc(tr("studio_studio_settings",{v16:''}))}</span></button>${productFeedback.navigation()}<div class="profile"><button class="profile-open" data-action="profile" title="${tr("user_profile")}" aria-label="${tr("user_profile")}">${personAvatar(state.user?.profile,state.user?.name)}<span>${esc(state.user?.profile?.name||state.user?.name||tr("studio_your_studio"))}<small>${tr("user_profile")}</small></span></button><button data-action="logout" title="${tr("studio_sign_out")}" aria-label="${tr("studio_sign_out")}">${icon('logout')}</button></div></div></aside>`;}
function renderWorkspace(){const d=state.data,p=d?.project,tab=state.tab,trialBar=DEMO?'':billing.trialBar();$('#app').innerHTML=`${trialBar}<div class="workspace ${trialBar?'billing-bar-layout':''}">${sidebar()}<div class="workspace-body"><header class="topbar"><div class="row">${iconBtn('menu','menu',tr("studio_open_navigation"))}<div class="breadcrumbs"><button data-action="projects">${tr("studio_projects")}</button>${p&&!['projects','studio-users','all-activity','all-comments','profile','billing','website'].includes(tab)?`${icon('right')}<span>${esc(p.name)}</span>`:''}</div></div><div class="row">${DEMO?`<button class="demo-indicator" data-action="demo-info">${tr("studio_interactive_demo")} `+icon('help')+'</button>':''}</div></header><main class="main-content" id="main">${DEMO||(tab==='projects'&&state.studioEmpty&&state.billing?.needs_onboarding)?'':billing.banner()}${tab==='website'?website.page():tab==='billing'?billing.page():['all-activity','all-comments'].includes(tab)?feedPage():tab==='profile'?profilePage():tab==='studio-users'?studioUsersPage():tab==='projects'?projectList():d?projectPage():empty(tr("studio_your_next_project_starts_here"),tr("studio_create_a_project_and_drop_in_your_design_files"),'new-project',tr("studio_create_a_project"))}</main></div></div>`;const m=$('[data-action="menu"]');if(m)m.classList.add('mobile-menu');}
