function showClientPresentationHelp(){
 if(!state.client||!state.present||activeModal||clientPresentationHelpShown)return;
 const key='studiodeck.clientPresentationHelp.hidden';
 try{if(localStorage.getItem(key)==='1')return;}catch{}
 clientPresentationHelpShown=true;
 let hidden=false;
 const showStep=step=>{
  openModal(tr(step===1?'presentation_help_title':'presentation_help_options_title'),`<div class="client-presentation-help"><div class="presentation-help-progress" aria-label="${esc(tr('presentation_help_step',{step}))}"><span class="${step===1?'current':''}"></span><span class="${step===2?'current':''}"></span><small>${tr('presentation_help_step',{step})}</small></div>${step===1?'<div class="presentation-help-keys" aria-hidden="true"><kbd>←</kbd><kbd>→</kbd></div>':''}<p>${tr(step===1?'presentation_help_arrows':matchMedia('(hover: hover)').matches?'presentation_help_options':'presentation_help_options_touch')}</p><label class="check-label"><input type="checkbox" role="switch" data-presentation-help-hide ${hidden?'checked':''}>${tr('presentation_help_dont_show_again')}</label><div class="modal-footer">${step===2?'<button type="button" class="button ghost" data-presentation-help-back>'+tr('presentation_help_back')+'</button>':''}${step===1?'<button type="button" class="button primary" data-presentation-help-next>'+tr('presentation_help_next')+icon('right')+'</button>':button(tr('dismiss'),'close-modal','primary')}</div></div>`);
  $('[data-presentation-help-hide]').addEventListener('change',event=>{hidden=event.target.checked;try{if(hidden)localStorage.setItem(key,'1');else localStorage.removeItem(key);}catch{}});
  $('[data-presentation-help-next]')?.addEventListener('click',()=>showStep(2));
  $('[data-presentation-help-back]')?.addEventListener('click',()=>showStep(1));
  const focusTimer=setTimeout(()=>$('.client-presentation-help .modal-footer .primary')?.focus(),20);
  clientPresentationHelpCleanup=()=>{clearTimeout(focusTimer);clientPresentationHelpCleanup=null;};
  if(step!==2)return;
  const sidebar=$('.presentation-sidebar'),handle=$('.presentation-sidebar-handle'),backdrop=$('.modal-backdrop'),modal=$('.modal');
  if(!handle)return;
  sidebar.classList.add('presentation-help-target');
  backdrop.classList.add('presentation-help-spotlight');
  const highlight=document.createElement('div');highlight.className='presentation-help-highlight';highlight.setAttribute('aria-hidden','true');backdrop.prepend(highlight);
  const position=()=>{
   const rect=handle.getBoundingClientRect(),left=rect.right+26,top=Math.max(12,Math.min(rect.top-12,innerHeight-modal.offsetHeight-12));
   Object.assign(highlight.style,{left:`${rect.left-5}px`,top:`${rect.top-5}px`,width:`${rect.width+10}px`,height:`${rect.height+10}px`});
   Object.assign(modal.style,{left:`${left}px`,top:`${top}px`,width:`${Math.min(400,innerWidth-left-16)}px`});
   modal.style.setProperty('--help-pointer-top',`${rect.top+rect.height/2-top}px`);
  };
  const observer=new ResizeObserver(position);observer.observe(modal);observer.observe(handle);
  window.addEventListener('resize',position);window.addEventListener('scroll',position,true);position();
  clientPresentationHelpCleanup=()=>{clearTimeout(focusTimer);observer.disconnect();window.removeEventListener('resize',position);window.removeEventListener('scroll',position,true);sidebar.classList.remove('presentation-help-target');clientPresentationHelpCleanup=null;};
 };
 showStep(1);
}
function openModal(title,content,wide=false){motionUi.close();clientPresentationHelpCleanup?.();if(!activeModal)previousFocus=document.activeElement;activeModal=true;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2>${iconBtn('close','close-modal',tr('close_dialog'))}</div>${content}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input:not([type="hidden"]),.modal textarea,.modal button')?.focus(),20);}
