    openModal(tr("studio_bring_your_ideas_together"),`${wizardSteps(3)}<p>${tr("studio_add_files_for")} <strong>${esc(w.details.name)}</strong>${tr("studio_we_ll_extract_the_pages_images_and_text_then_open_your_project_when_processing_finishes")}</p><form data-form="new-project-files">${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}<div class="dropzone wizard-dropzone" data-wizard-dropzone><button type="button" class="wizard-file-picker" data-action="wizard-browse">${icon('upload')}<strong>${tr("studio_drop_your_files_here_or_browse")}</strong><span>${tr("studio_pdf_powerpoint_excel_images")}</span><small>${tr("studio_up_to_100_mb_per_file_120_mb_per_batch_20_files")}</small></button><input type="file" id="wizard-file-input" hidden multiple accept=".pdf,.ppt,.pptx,.xls,.xlsx,.csv,.jpg,.jpeg,.png,.webp"></div>${button(tr("studio_from_google_drive"),'wizard-drive','ghost','','folder')}<div class="wizard-file-list" aria-live="polite">${displayFiles.length?`<p class="form-hint">${tr("studio_file_selected",{v0:displayFiles.length,v1:displayFiles.length===1?'':'s',v2:w.driveSelection?'Google Drive':bytes(displayFiles.reduce((total,f)=>total+f.size,0))})}</p>${displayFiles.map((f,n)=>`<div class="wizard-file-row">${icon('file')}<span><strong>${esc(f.name)}</strong><small>${w.driveSelection?tr("studio_from_google_drive"):bytes(f.size)}</small></span>${iconBtn('close','wizard-remove-file',tr("studio_remove",{v0:f.name}),`data-index="${n}"`)}</div>`).join('')}`:`<p class="form-hint">${tr("studio_choose_one_or_more_files_you_can_add_more_later")}</p>`}</div><div class="modal-footer wizard-footer">${!w.created?button(tr("studio_back"),'wizard-back','ghost','','left'):''}<button type="submit" name="finish" value="skip" class="button ghost">${tr("studio_add_files_later")}</button><button type="submit" name="finish" value="upload" class="button primary" ${displayFiles.length?'':'disabled'}>${icon('arrow')}${w.created?tr("studio_retry_upload"):tr("studio_create_process_files")}</button></div></form>`);
    const input=$('#wizard-file-input'),zone=$('[data-wizard-dropzone]');
