function addWizardFiles(files){
    const w=newProjectWizard;if(!w||w.busy)return;
    const next=[...w.files];for(const file of files)if(!next.some(f=>f.name===file.name&&f.size===file.size&&f.lastModified===file.lastModified))next.push(file);
    const unsupported=next.find(f=>! /\.(pdf|pptx?|xlsx?|csv|jpe?g|png|webp)$/i.test(f.name));
    const error=unsupported?tr("studio_isn_t_a_supported_file_please_choose_pdf_powerpoint_excel_csv_jpg_png_or_webp_files",{v0:unsupported.name}):uploadSelectionError(next);
    if(error){projectWizardFiles(error);return;}w.files=next;w.driveSelection=null;projectWizardFiles();
}
async function finishProjectWizard(skip=false){
    const w=newProjectWizard;if(!w||w.busy)return;
    if(!skip){const error=!w.files.length&&!w.driveSelection?.files.length?tr("studio_choose_at_least_one_file_or_select_add_files_later"):uploadSelectionError(w.files);if(error){projectWizardFiles(error);return;}}
    w.busy=true;document.querySelectorAll('.modal button,.modal input').forEach(el=>el.disabled=true);
    const status=document.createElement('p');status.className='form-hint';status.setAttribute('role','status');status.textContent=w.created?tr("studio_opening_your_project"):tr("studio_creating_your_project");$('.wizard-file-list').prepend(status);
    try{
        if(!w.created){w.created=await api('create_project',{name:w.details.name,description:w.details.description,visibility:'team',starting_pack:w.selected,archive_project_id:w.archiveProjectId,billing_intent:w.billingIntent});if(w.firstProject)onboarding.created(w.created.project_id);state.studioEmpty=false;}
        state.tab='overview';await openProject(w.created.project_id,w.created.iteration_id);await loadProjects();
        w.busy=false;closeModal();
        if(skip){toast(tr("studio_your_project_is_ready_add_files_whenever_you_re_ready"));return;}
        if(w.driveSelection)await uploadDriveFiles(w.driveSelection,'','',true);else await uploadFiles(w.files,'','',true);
    }catch(error){w.busy=false;if(processingView.visible)hideProcessing();newProjectWizard=w;projectWizardFiles(error.message);}
}
