const filePreviewKind=file=>fileType(file)==='csv'?'csv':/^(jpe?g|png|webp|gif|svg)$/.test(fileType(file))?'image':'';
function filePreviewButton(file){const kind=filePreviewKind(file);return kind?iconBtn('eye','preview-'+kind,kind==='csv'?tr("preview_csv"):tr("preview_image"),`data-id="${esc(file.id)}"`):'';}
async function previewFile(id){
 const file=downloadFile(id),kind=filePreviewKind(file);if(!kind)return;
 const label=kind==='csv'?'CSV':tr('image_lowercase');
 openModal(esc(file.name),`<div data-file-preview role="status"><p class="notice">${tr('loading_preview',{type:label})}</p></div><div class="modal-footer">${button(tr("download_original"),'download','primary',`data-id="${esc(id)}"`,'download')}</div>`,true);
 $('.modal').classList.add('file-preview-dialog',kind+'-preview-dialog');
 const target=$('[data-file-preview]'),params=new URLSearchParams({action:'file',id,iteration:state.data.iteration.id});
 let imageUrl;
 try{
  const response=await fetch(DEMO?demoFile(id).url:'api.php?'+params,{credentials:'same-origin',headers:resourceHeaders()});
  if(!response.ok)throw Error(tr("preview_unavailable"));
  if(kind==='csv'){
   const text=await response.text();
   if(target.isConnected){target.removeAttribute('role');target.innerHTML=csvPreview(text,esc);}
  }else{
   imageUrl=URL.createObjectURL(await response.blob());
   const image=new Image();image.alt=file.name;image.src=imageUrl;await image.decode();
   if(target.isConnected){target.removeAttribute('role');target.classList.add('extracted-asset-preview');target.replaceChildren(image);}
  }
 }catch{if(target.isConnected)target.innerHTML=`<p class="notice">${tr('preview_failed',{type:label})}</p>`;}
 finally{if(imageUrl)URL.revokeObjectURL(imageUrl);}
}
