function budgetModal(id=''){
    const item=state.data.budget.find(x=>x.id===id);if(id&&!item)return;if(item&&communication.budgetSource(item))return;if(!id){editCostModal({});return;}
    openModal(esc(item.label),`<p>${esc(item.vendor||tr("vendor_to_be_confirmed"))}</p><div class="budget-total">${budgetAmount(item)===null?tr("to_be_specified"):money(budgetAmount(item))}</div>${budgetIsRange(item)?`<p>${tr("source_range")} ${money(item.min_amount_cents)} – ${money(item.max_amount_cents)} · ${tr('towards_luxury',{percent:item.range_percent||0})}</p>`:''}<div class="row wrap"><span class="tag">${esc(['estimate','quote','unknown'].includes(item.kind)?tr(item.kind):item.kind)}</span>${Number(item.is_optional)?`<span class="tag">${tr("optional")} · ${item.selected?tr("selected"):tr("not_selected")}</span>`:''}${Number(item.included)?`<span class="tag">${tr("already_included_in_parent")}</span>`:''}</div><p>${esc(item.note||tr("no_additional_source_notes_have_been_recorded"))}</p>${item.relationship_evidence?`<details class="subquote-review"><summary>${item.relationship_origin==='auto'?tr("automatically_linked_source_evidence"):tr("quote_relationship_source_evidence")}</summary><p class="subquote-evidence">${esc(item.relationship_evidence)}</p>${editable()&&item.relationship_origin==='auto'?button(tr("undo_automatic_link"),'unlink-subquote','small',`data-id="${esc(item.id)}"`):''}</details>`:''}<div class="modal-footer">${item.source_version_id?button(fileTypeLogo(downloadFile(item.source_version_id))+tr("source_quote"),'download','',`data-id="${esc(item.source_version_id)}"`,'download'):''}${editable()?button(tr("edit_cost"),'edit-cost','primary',`data-id="${esc(item.id)}"`,'edit'):state.client?button(tr("ask_a_question_"),'feedback','primary','','chat'):''}</div>`);
}
function editCostModal(item){
    if(item.confirmation){communication.budgetSource(item);return;}
    if(!requireDraft())return;const excluded=new Set([item.id]);let changed=true;while(changed){changed=false;for(const x of state.data.budget)if(excluded.has(x.parent_id)&&!excluded.has(x.id)){excluded.add(x.id);changed=true;}}
    const type=budgetIsRange(item)?'range':item.amount_cents!=null?'fixed':'unknown';
    openModal(item.id?tr("studio_refine_this_cost"):tr("studio_make_the_numbers_clearer"),`<form data-form="budget"><input type="hidden" name="id" value="${esc(item.id||'')}"><label>${tr("studio_cost_or_quote")}<input name="label" value="${esc(item.label||'')}" placeholder="${tr("studio_custom_kitchen_cabinetry")}" required maxlength="300"></label><label>${tr("studio_vendor")}<input name="vendor" value="${esc(item.vendor||'')}" maxlength="200"></label><label>${tr("studio_price_type")}<select name="price_type" id="budget-price-type">${[['fixed',tr("studio_fixed_price")],['range',tr("studio_price_range")],['unknown',tr("still_to_be_specified")]].map(([v,t])=>`<option value="${v}" ${v===type?'selected':''}>${t}</option>`).join('')}</select></label><div data-budget-fields="fixed" ${type!=='fixed'?'hidden':''}><label>${tr("studio_fixed_price_2")}<input name="amount" type="number" step="0.01" value="${item.amount_cents!=null?item.amount_cents/100:''}"></label></div><div class="field-row" data-budget-fields="range" ${type!=='range'?'hidden':''}><label>${tr("studio_budget_price")}<input name="min_amount" type="number" min="0" step="0.01" value="${item.min_amount_cents!=null?item.min_amount_cents/100:''}"></label><label>${tr("studio_luxury_price")}<input name="max_amount" type="number" min="0" step="0.01" value="${item.max_amount_cents!=null?item.max_amount_cents/100:''}"></label></div><label class="check-label"><input type="checkbox" name="is_optional" ${Number(item.is_optional)?'checked':''}>${tr("studio_optional_item_only_count_when_selected")}</label><label>${tr("studio_status")}<select name="kind"><option value="estimate" ${item.kind!=='quote'?'selected':''}>${tr("studio_estimate")}</option><option value="quote" ${item.kind==='quote'?'selected':''}>${tr("studio_quoted")}</option></select></label><label>${tr("studio_part_of_another_quote")}<select name="parent_id"><option value="">${tr("studio_separate_project_cost")}</option>${state.data.budget.filter(x=>!excluded.has(x.id)&&!x.confirmation).map(x=>`<option value="${esc(x.id)}" ${x.id===item.parent_id?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label><label class="check-label"><input name="included" type="checkbox" ${Number(item.included)?'checked':''}>${tr("studio_included_in_the_parent_quote_s_total")}</label><label>${tr("studio_notes_exclusions")}<textarea name="note" rows="3" maxlength="2000">${esc(item.note||'')}</textarea></label>${formFooter(tr("studio_save_cost"))}</form>`);syncBudgetPriceFields();
}
function syncBudgetPriceFields(){const type=$('#budget-price-type')?.value;document.querySelectorAll('[data-budget-fields]').forEach(el=>{el.hidden=el.dataset.budgetFields!==type;el.querySelectorAll('input').forEach(input=>{input.disabled=el.hidden;input.required=!el.hidden;});});}
document.addEventListener('change',e=>{if(e.target.id==='budget-price-type')syncBudgetPriceFields();});
function studioLogoUrl(){if(DEMO&&state.studio?.logo)return state.studio.logo;return 'api.php?'+new URLSearchParams({action:'studio_logo',studio_id:state.studio?.id||'',v:state.logoVersion||0});}
function imageUploadField(kind,preview,showFormats=true){const avatar=kind==='avatar';return `<div class="dropzone project-logo-dropzone" data-image-upload="${kind}"><button type="button" class="project-logo-picker" data-image-upload-picker aria-label="${avatar?tr('choose_avatar'):tr('choose_logo')}"><span class="project-settings-logo-preview" data-image-upload-preview>${preview}</span><span>${tr(avatar?'drop_photo':'drop_logo')} <u>${tr('browse')}</u></span>${showFormats?`<small>${tr('image_formats')}</small>`:''}</button><input type="file" name="${avatar?'avatar':'logo'}" data-image-upload-input accept="image/png,image/jpeg,image/webp" hidden></div><p class="form-hint" data-image-upload-status role="status"></p>`;}
function settingsLogoUpload(studio=false){return `<section class="project-settings-logo">
            <div class="settings-heading"><h3>${tr(studio?'studio_logo_label':'studio_presentation_logo')}</h3>${settingsHelp('logo-priority-tooltip',tr(studio?'studio_logo_label':'studio_presentation_logo'),[...(studio?[]:[tr('studio_project_logo_first_then_studio_logo_then_studiodeck')]),tr('image_formats'),tr('studio_click_the_logo_to_change_it_changes_are_applied_when_you_save')].join('\n'),studio?tr('studio_setting_help',{name:tr('studio_logo_label')}):tr('studio_how_the_presentation_logo_is_chosen'))}</div>
            <div class="dropzone project-logo-dropzone" data-project-logo-drop><button type="button" class="project-logo-picker" data-action="choose-project-logo" aria-label="${tr(studio?'choose_logo':'studio_choose_presentation_logo')}"><span class="project-settings-logo-preview" data-logo-preview>${studio?(state.studio?.has_logo?`<img class="studio-logo" src="${studioLogoUrl()}" alt="${tr('studio_current_studio_logo')}">`:defaultBrand()):(state.data.branding?.logo?`<img class="studio-logo" src="${esc(state.data.branding.logo)}" alt="${tr('studio_current_presentation_logo')}">`:defaultBrand())}</span><span>${tr("drop_logo")} <u>${tr("browse")}</u></span></button><input type="file" id="project-logo-input" name="logo" accept="image/png,image/jpeg,image/webp" hidden></div>
            <small data-logo-status role="status"></small>
            ${button(tr(studio?'studio_remove_logo':'studio_remove_project_logo'),'clear-project-logo','small ghost',(studio?state.studio?.has_logo:state.data.branding?.has_project_logo)?'':'hidden')}
        </section>`;}
function settingsHelp(id,label,text,accessibleLabel=tr('studio_setting_help',{name:label})){
 return `<span class="settings-help"><button type="button" class="settings-help-button" aria-label="${esc(accessibleLabel)}" aria-describedby="${id}">${icon('help')}</button><span class="settings-help-tooltip" role="tooltip" id="${id}">${esc(text)}</span></span>`;
}
function studioSettings(){
 if(!DEMO&&state.studio?.role!=='admin'){openModal(tr("studio_studio_settings_2"),`<p><strong>${esc(state.studio?.name||'')}</strong></p><p>${tr("studio_a_studio_admin_can_update_the_name_logo_and_starting_pack")}</p>`);state.settingsOpen=true;syncWorkspaceUrl();return;}
 const fontHelp=[tr('studio_font_hint'),`${tr('studio_font_classic')}: ${tr('studio_font_classic_description')}.`,`${tr('studio_font_modern')}: ${tr('studio_font_modern_description')}.`].join('\n');
 openModal(tr("studio_studio_settings_2"),`<form data-form="studio-theme" class="studio-settings-content">${settingsLogoUpload(true)}${!DEMO?`<div class="notice pack-summary"><div class="settings-heading"><strong>${tr("studio_studio_starting_pack")}</strong>${settingsHelp('studio-pack-help',tr('studio_studio_starting_pack'),tr('studio_reusable_slides_and_client_reference_documents_for_every_new_project'))}</div>${button(tr("studio_manage_starting_pack"),'pack-library','small')}</div>`:''}${businessTypeField(state.studio?.business_type||'interior',esc,settingsHelp)}<div class="settings-field"><div class="settings-heading"><label for="studio-language">${tr("studio_language")}</label>${settingsHelp('studio-language-help',tr('studio_language'),tr('projects_use_the_studio_language_unless_a_project_has_its_own_language'))}</div>${languageSelect(state.studio?.language||'en',false).replace('<select ','<select id="studio-language" ')}</div><label>${tr("studio_studio_name")}<input name="name" value="${esc(state.studio?.name||'')}" maxlength="100" required></label><fieldset class="studio-options" aria-labelledby="studio-font-label"><legend><span class="settings-heading"><span id="studio-font-label">${tr('studio_font_style')}</span>${settingsHelp('studio-font-help',tr('studio_font_style'),fontHelp)}</span></legend><div class="studio-font-options">${['serif','sans'].map(font=>`<label class="studio-choice studio-font-${font}"><input type="radio" name="font" value="${font}" ${cleanStudioTheme(state.studioTheme).font===font?'checked':''}><strong>${tr(font==='serif'?'studio_font_classic':'studio_font_modern')}</strong></label>`).join('')}</div></fieldset>${formFooter(tr("studio_save_studio_settings"))}</form>`);bindSettingsLogoUpload($('[data-form="studio-theme"]'));state.settingsOpen=true;syncWorkspaceUrl();
}
function commentThreadList(comments,feed=false){
 const canReply=feed||state.client||state.data?.can_edit!==false;
 return commentThreads(comments,commentView).map(({comment:c,replies})=>`<section class="comment-thread" data-thread-id="${esc(c.id)}"><article class="${feed?'timeline-item':'feedback-item'} comment-card" data-comment-id="${esc(c.id)}">${commentPreview(c)}<div class="comment-content"><div class="comment-heading">${commentAuthor(c)}<div class="comment-heading-actions">${canReply?button(tr("reply"),'reply-comment','small ghost',`data-id="${esc(c.id)}"`,'chat'):''}</div></div>${feed?`<h3>${esc(c.project_name)} · ${tr("iteration")} ${c.iteration_number}</h3>`:''}${c.annotation?`<span class="annotation-label">${tr(c.annotation.image_version_id?"pin_on_variation":"pin_on_original")}</span>`:""}<p class="comment-body">${mentionBody(c.body,c.mentions)}</p>${communication.badge(c)}${editable()&&c.iteration_id===state.data?.iteration.id?button(tr("checklist_add"),"checklist-from-comment","small ghost",`data-id="${esc(c.id)}"`):''}<div class="comment-status" ${c.confirmation?'hidden':''}>${button(tr(Number(c.answered)?"mark_as_unanswered":"mark_as_answered"),'toggle-comment-answered',`small comment-answered ${Number(c.answered)?'is-answered':''}`,`data-id="${esc(c.id)}" aria-pressed="${!!Number(c.answered)}" aria-label="${Number(c.answered)?tr("mark_as_unanswered"):tr("mark_as_answered")}"`,'check')}</div></div></article><div class="comment-replies" aria-label="${tr("replies")}">${replies.map(reply=>`<article class="comment-reply" data-comment-id="${esc(reply.id)}">${commentAuthor(reply)}<p class="comment-body">${mentionBody(reply.body,reply.mentions)}</p>${communication.badge(reply)}</article>`).join('')}</div></section>`).join('');
}
function commentControls(){return `<div class="comment-controls"><button type="button" class="comment-show-answered" role="switch" aria-checked="${commentView.showAnswered}" data-action="show-answered"><span class="comment-switch" aria-hidden="true"></span>${tr("show_answered")}</button>${button(`${tr("sort")} ${commentView.sort==='newest'?tr("newest_first"):tr("oldest_first")}`,'sort-comments','small',`title="${tr(commentView.sort==='newest'?'switch_sort_oldest':'switch_sort_newest')}"`,commentView.sort==='newest'?'down':'up')}</div>`;}
function saveCommentDrafts(){for(const form of document.querySelectorAll('[data-form="comment-reply"]'))commentReplyDrafts.set(form.elements.parent_id.value,form);}
function restoreCommentDrafts(){for(const [id,form] of commentReplyDrafts){const thread=document.querySelector(`${activeModal?'.modal ':''}[data-thread-id="${CSS.escape(id)}"]`);if(thread&&!thread.querySelector('[data-form="comment-reply"]'))thread.querySelector('.comment-replies').append(form);}}
async function changeCommentView(control,property){
 const modal=!!control.closest('.modal'),previous=commentView[property],controls=control.closest('.comment-controls').querySelectorAll('button');saveCommentDrafts();controls.forEach(b=>b.disabled=true);
 commentView[property]=property==='sort'?(previous==='newest'?'oldest':'newest'):!previous;
 try{if(modal)feedbackModal();else{await loadFeed();render();restoreCommentDrafts();}}
 catch(error){commentView[property]=previous;throw error;}finally{controls.forEach(b=>b.disabled=false);}
}
async function toggleCommentAnswered(control){
 const modal=!!control.closest('.modal'),comment=(modal?state.data.comments:state.feedItems).find(c=>c.id===control.dataset.id);if(!comment||comment.parent_id)return;
 saveCommentDrafts();control.disabled=true;
 try{
  const result=await api('comment_answered',{iteration:comment.iteration_id||state.data.iteration.id,id:comment.id,answered:!Number(comment.answered)});
  for(const c of [...(state.data?.comments||[]),...(state.data?.communication?.comments||[]),...(state.feedItems||[])])if(c.id===result.id)c.answered=result.answered;
  annotations.redraw();if(modal)feedbackModal();else{await reloadCommentFeed();restoreCommentDrafts();}
  toast(result.answered?tr("studio_marked_answered"):tr("studio_comment_reopened"));
 }finally{control.disabled=false;}
}
function feedbackModal(annotation=null){
 if(communication.enabled()){communication.feedback(state.present?slideDefs()[state.slide].id:'general',annotation);return;}
 const slide=state.present?slideDefs()[state.slide].id:'general',comments=state.data.comments.filter(c=>c.slide===slide||slide==='general'),existing=$('[data-form="feedback"]'),draft=existing?.dataset.iteration===state.data.iteration.id&&existing.elements.slide.value===slide?existing.elements.body.value:'';
 annotation??=existing?.dataset.annotation?JSON.parse(existing.dataset.annotation):null;
 saveCommentDrafts();
 const visible=commentThreads(comments,commentView).flatMap(t=>[t.comment,...t.replies]);
 openModal(tr('comment_count',{count:comments.length}),`${communication.enabled()&&!state.present?button(communication.t('Communication'),'comm-show','small','','chat'):''}${state.present?`<p>${esc(slideDefs()[state.slide].title)}</p>`:`<p>${tr("comments_on_this_iteration")}</p>`}${commentControls()}<div class="feedback-list">${commentThreadList(comments)||`<p class="muted">${comments.length&&!commentView.showAnswered?tr("no_unanswered_comments_turn_on_show_answered_to_include_completed_threads"):tr("no_comments_yet")}</p>`}</div>${state.client||state.data.can_edit!==false?`<form data-form="feedback" data-iteration="${esc(state.data.iteration.id)}" ${annotation?`data-annotation="${esc(JSON.stringify(annotation))}"`:""}>${annotation?`<p class="notice">${tr("feedback_pin_selected")}</p>`:""}<input type="hidden" name="slide" value="${esc(slide)}"><label>${tr("add_a_comment")}<textarea name="body" rows="3" maxlength="4000" required>${esc(draft)}</textarea></label>${formFooter(tr("add_comment"),'chat')}</form>`:''}`);
 restoreCommentDrafts();hydrateCommentPreviews();markCommentsRead(visible).catch(e=>toast(e.message));
}

function replyComment(buttonElement){
 const thread=buttonElement.closest('.comment-thread');if(!thread)return;
 const existing=thread.querySelector('[data-form="comment-reply"]');if(existing){existing.querySelector('textarea').focus();return;}
 const modal=!!thread.closest('.modal'),comments=modal?state.data.comments:state.feedItems;
 const comment=comments.find(c=>c.id===buttonElement.dataset.id);if(!comment||comment.parent_id)return;
 const iid=comment.iteration_id||state.data?.iteration.id;
 thread.querySelector('.comment-replies').insertAdjacentHTML('beforeend',`<form data-form="comment-reply" class="comment-reply-form"><input type="hidden" name="parent_id" value="${esc(comment.id)}"><input type="hidden" name="iteration" value="${esc(iid)}"><input type="hidden" name="slide" value="${esc(comment.slide)}"><label>${tr("reply_to")} ${esc(comment.profile?.name||comment.author)}<textarea name="body" rows="3" maxlength="4000" required placeholder="${tr("write_a_reply")}"></textarea></label><div class="comment-actions">${button(tr("cancel"),'cancel-comment-reply','small ghost')}<button type="submit" class="button primary small">${icon('send')}${tr("post_reply")}</button></div></form>`);
 thread.querySelector('textarea').focus();
}
function revealComment(id){if(id)document.querySelector(`[data-comment-id="${CSS.escape(id)}"]`)?.scrollIntoView({block:'nearest'});}
async function reloadCommentFeed(){const count=state.feedOffset||100;await loadFeed();while(state.feedMore&&state.feedOffset<count)await loadFeed(true);render();}

function presentationMetadata(def){
 if(!def?.visual)return '';
 const r=def.record;
 return `<div class="preview-slide-metadata"><span>${r&&!r.manual?tr('detected_type')+' ':''}${esc(slideTypeName(def))}</span>${r&&situations[def.situation]?`<span>${esc(situations[def.situation])}</span>`:''}${r?.image_version_id?`<span>${tr('ai_visualization')}</span>`:''}</div>`;
}

function previewBar(){
    if(state.client)return '';const def=slideDefs()[state.slide],s=def?.record,edit=editable(),palette=studioPalettes[cleanStudioTheme(state.studioTheme).palette];
    return `<div class="preview-bar" style="--green:${palette.colors[0]};--on-accent:#fff;--surface:#fff;--ink:#303230;--line:#ccc;--soft:${palette.colors[1]}">${button(tr("back_to_studio"),'exit-preview','ghost small','','left')}<span class="preview-slide-label">${esc(def?.title||tr("studio_presentation_preview"))}</span>${presentationMetadata(def)}${edit&&def?`<div class="row">${!def.sourceOnly&&!s?.legacy?button(tr("studio_edit_slide_2"),'edit-slide','small',`data-id="${esc(s?.id||def.id)}"`,'edit'):''}${button(def.hidden?tr("studio_show"):tr("studio_hide"),'visibility-slide','small',`data-id="${esc(def.id)}" data-operation="${def.hidden?'show':'hide'}"`,'eye')}${button('Delete','delete-slide','small danger-text',`data-id="${esc(def.id)}"`,'minus')}</div>`:''}</div>`;
}
function projectStylePreview(t){return `<div class="project-style-sample project-preview" data-project-style-preview style="${esc(projectThemeStyle(t))}"><small>${tr("studio_your_presentation_2")}</small><h3>${tr("studio_a_space_to_feel_at_home")}</h3><div>${t.colors.map(c=>`<i style="background:${esc(c)}"></i>`).join('')}<span>${tr("studio_explore_the_concept")}</span></div></div>`;}
function updateProjectStylePreview(e){const form=e.target.closest('[data-form="theme"]');if(!form)return;const data=Object.fromEntries(new FormData(form)),colors=Object.entries(data).filter(([key])=>key.startsWith('color')).map(([,value])=>value);form.querySelector('[data-project-style-preview]').outerHTML=projectStylePreview({...data,colors});form.querySelectorAll('[data-background-mode]').forEach(el=>el.hidden=el.dataset.backgroundMode!==data.mode);}
document.addEventListener('input',updateProjectStylePreview);document.addEventListener('change',updateProjectStylePreview);

function themeModal(){
    if(!requireDraft())return;const t=theme(),designWhite=projectThemeVariables({...t,mode:'light',light_background:''})['--deck-bg'];
    const choices=(name,options,selected)=>options.map(([value,label])=>`<label class="style-choice"><input type="radio" name="${name}" value="${esc(value)}" ${selected===value?'checked':''}><span ${name==='font'?`style="font-family:${value==='serif'?'Georgia,serif':'Arial,sans-serif'}"`:''}>${label}</span></label>`).join('');
    const colors=(name,options,selected)=>options.map(([value,label])=>`<label class="background-choice"><input type="radio" name="${name}" value="${value}" ${selected===value?'checked':''}><i style="background:${value}"></i><span>${label}</span></label>`).join('');
    const light=[[designWhite,tr("studio_design_white")],['#f6f0e5',tr("studio_ivory")],['#edf1f3',tr("studio_mist")],['#f4eaea',tr("studio_blush")],['#edf1e8',tr("studio_sage")]];
    const dark=[['#152235',tr("studio_midnight")],['#111314',tr("studio_soft_black")],['#253128',tr("studio_pine")],['#302838',tr("studio_plum")],['#322a25',tr("studio_espresso")]];
    // Preserve an existing custom background within the five choices.
    if(t.light_background&&!light.some(([color])=>color===t.light_background))light[0]=[t.light_background,tr("studio_current_light")];
    if(!dark.some(([color])=>color===t.background))dark[0]=[t.background,tr("studio_current_dark")];
    openModal(tr("studio_project_presentation_style"),`<form data-form="theme" class="project-style-layout"><aside class="style-preview-column">${projectStylePreview({...t,light_background:t.light_background||designWhite})}<p class="form-hint">${tr("studio_live_preview_changes_apply_when_you_save")}</p></aside><div class="style-settings"><fieldset class="style-options"><legend>${tr("studio_presentation_typography")}</legend><div class="style-choice-row">${choices('font',[['serif',tr("studio_editorial_serif")],['sans',tr("studio_modern_sans")]],t.font)}</div></fieldset><fieldset class="style-options"><legend>${tr("studio_presentation_background")}</legend><div class="style-choice-row">${choices('mode',[['light',tr("studio_light_background")],['dark',tr("studio_dark_background")]],t.mode)}</div></fieldset><fieldset class="style-options" data-background-mode="light" ${t.mode==='light'?'':'hidden'}><legend>${tr("studio_light_color")}</legend><div class="background-choices">${colors('light_background',light,t.light_background||designWhite)}</div></fieldset><fieldset class="style-options" data-background-mode="dark" ${t.mode==='dark'?'':'hidden'}><legend>${tr("studio_dark_color")}</legend><div class="background-choices">${colors('background',dark,t.background)}</div></fieldset><label>${tr("studio_project_palette_extracted_from_your_designs")}</label><div class="theme-editor-swatches">${t.colors.map((c,n)=>`<input type="color" name="color${n}" value="${c}" aria-label="${tr("studio_palette_color",{v2:n+1})}">`).join('')}</div>${formFooter(tr("studio_apply_to_presentation"),'check')}</div></form>`,true);$('.modal').classList.add('style-dialog');
}

function editImageModal(id){const f=state.data.files.find(x=>x.id===id);if(!f||!requireDraft())return;openModal(tr("change_with_ai"),imagePromptForm('image-edit',`<input type="hidden" name="version_id" value="${esc(id)}">`),true);}


function manageLinks(){const shares=state.data.shares||[];openModal(tr("studio_your_shared_presentations"),`<p>${tr("studio_each_link_opens_only_the_iteration_it_was_created_for_revoke_a_link_to_stop_access")}</p>${shares.map(s=>`<div class="history-item"><span>${esc(s.email)}<small>${s.revoked?tr("studio_revoked"):`${tr("studio_expires")} `+new Date(s.expires_at*1000).toLocaleDateString(dateLocale())}</small></span>${s.revoked?'':button(tr("studio_revoke"),'revoke-share','small',`data-id="${esc(s.id)}"`)}</div>`).join('')||`<p class="muted">${tr("studio_there_are_no_active_links_recorded_for_this_iteration")}</p>`}<div class="modal-footer">${button(tr("studio_share_presentation"),'share','primary','','send')}</div>`);}
async function download(id){let name,url;if(DEMO){const f=demoFile(id);if(!f)throw Error(tr('error_this_source_is_not_available'));name=f.name;url=f.url;}else{const f=state.data.files.flatMap(f=>[f,...f.history]).find(v=>v.id===id);if(!f)throw Error(tr('error_this_source_is_not_part_of_this_iteration'));const p=new URLSearchParams({action:'file',id,iteration:state.data.iteration.id}),headers=resourceHeaders();const r=await fetch('api.php?'+p,{credentials:'same-origin',headers});if(!r.ok){const b=await r.json();throw Error(translateError(b.error||'Download unavailable.'));}name=f.name;url=URL.createObjectURL(await r.blob());}const a=document.createElement('a');a.href=url;a.download=name;a.click();if(!DEMO)setTimeout(()=>URL.revokeObjectURL(url),20000);}
async function uploadFiles(files,asset='',category='',projectSetup=false){if(!files.length||!requireDraft())return;const sizeError=uploadSelectionError(files);if(sizeError){openModal(tr("studio_upload_needs_attention"),`<p>${esc(sizeError)}</p><div class="modal-footer">${button(tr("studio_got_it"),'close-modal','primary')}</div>`);return;}const fd=new FormData();fd.append('iteration',state.data.iteration.id);if(category)fd.append('category',category);if(asset)fd.append('replace_asset',asset);for(const f of files)fd.append('files[]',f);
    showProcessing(true,[],projectSetup);
    try{const result=await api('upload',fd);processingView.uploading=false;processingView.ids=result.ids||[];state.tab='overview';await refresh();renderProcessing();}
    catch(e){processingView.uploading=false;processingView.error=e.message;renderProcessing();throw e;}
}
function chooseFiles(asset='',category=''){if(requireDraft())uploader.open({asset,category});}
async function uploadDriveFiles(selection,asset='',category='',projectSetup=false){
 if(!requireDraft())return;const iid=state.data.iteration.id;showProcessing(true,[],projectSetup);
 try{const result=await api('drive_import',{iteration:iid,folder:selection.folder,files:selection.files,replace_asset:asset,category});processingView.uploading=false;processingView.ids=result.ids||[];state.tab='overview';await refresh();renderProcessing();}
 catch(e){processingView.uploading=false;processingView.error=e.message;renderProcessing();throw e;}
}
async function askBudget(q){
    if(state.busy)return;const context={iteration:state.data.iteration.id,slide:state.present?slideDefs()[state.slide]?.id||'budget':'budget'};
    state.chat.push({role:'user',text:q});state.busy=true;render();
    try{const r=await api('budget_chat',{...context,question:q});if(state.data?.iteration.id!==context.iteration)return;state.chat.push({role:'assistant',text:r.answer,sources:r.sources,citations:r.citations});if(state.data.events&&r.activity_event)state.data.events.unshift(r.activity_event);}
    catch(e){if(state.data?.iteration.id===context.iteration)state.chat.push({role:'assistant',text:e.message});}
    finally{state.busy=false;render();document.querySelectorAll('[data-chat-messages]').forEach(el=>el.scrollTo(0,99999));}
}
function startPresentation(slide=0){if(activeModal)closeModal();if(!slideDefs().length){toast(tr("studio_show_a_slide_in_the_editor_before_previewing"));return;}if(!state.client)onboarding.reviewed();state.present=true;state.slide=Math.max(0,slide);state.imageIndex=0;state.zoom=1;render();if(state.presentationMode==='scroll')scrollToSlide(slideDefs()[state.slide]?.id,{smooth:false});else window.scrollTo(0,0);api('view_event',{iteration:state.data.iteration.id,slide:slideDefs()[state.slide].id}).catch(()=>{});}
function moveSlide(n){const next=Math.max(0,Math.min(state.slide+n,slideDefs().length-1));if(state.presentationMode==='scroll'&&state.present){state.slide=next;scrollToSlide(slideDefs()[next]?.id,{focus:!magnifiedPhoto,smooth:!magnifiedPhoto});syncScrollPresentationContext();syncWorkspaceUrl(true);return;}if(next===state.slide)return;animateSlideChange(()=>{state.slide=next;state.imageIndex=0;state.zoom=1;render();window.scrollTo(0,0);},n);}
