let routeLoading=false;
async function start(){
    routeLoading=true;let success=false;
    try{
        const match=location.hash.match(/^#\/(view|login|preview)\/([^/]+)$/);
        if(match?.[1]==='login'||match?.[1]==='view'){location.replace('/login'+location.hash);return;}

        state.client=false;state.shareToken='';state.clientShareId='';state.accountClientProject='';const session=await api('session');applySession(session);
        if(TOUR_MODE){await loadProjects();state.tab='overview';await openProject('tour-project',null,false,true);appTourGuide({state,stats:tourData.stats,esc,prepare:prepareAppTourStep}).start();success=true;return;}
        const route=readWorkspaceRoute(location),clientRoute=readClientRoute(location);
        if(!state.user){if(route||clientRoute||location.pathname==='/choose')sessionStorage.setItem('studiodeck.returnTo',location.pathname+location.search);location.replace('/login');return;}
        if(clientRoute){await openClientProject(clientRoute.projectId,clientRoute.iteration,clientRoute.slide,clientRoute.presentationMode||'slides');success=true;return;}
        if(location.pathname==='/choose'){await showDestinations();success=true;return;}
        if(match?.[1]==='preview'){const d=await api('deck',{iteration:match[2]});await loadProjects();state.tab='overview';await openProject(d.project.id,d.iteration.id,true);success=true;return;}
        if(route)await openWorkspaceRoute(route);else await showDestinations(true);success=true;
    }catch(error){routeError(error);}
    finally{routeLoading=false;if(success)syncWorkspaceUrl(true);}
}
function routeError(error){
    if(activeModal)closeModal();if(magnifiedPhoto)closePhotoLightbox(false);
    clearTimeout(state.poll);stopSlideMedia();stopScrollPresentation();cancelSlideMotion();scrollImageObserver?.disconnect();
    state.present=false;state.routeFailed=true;clearPresentationTheme();
    document.body.classList.remove('presenting','presentation-reading','website-editing');
    if(isPresentationFullscreen())exitPresentationFullscreen().catch(()=>{});
    mountErrorPage($('#app'),error,{language:getLanguage(),signedIn:!!state.user,email:state.user?.email});
}
function syncWorkspaceUrl(replace=false){
    if(TOUR_MODE)return;
    if(routeLoading||!state.user)return;
    const accountPath=state.client&&state.accountClientProject?clientProjectUrl(state.accountClientProject,state.data?.iteration.id,slideDefs()[state.slide]?.id,state.presentationMode):state.tab==='destinations'&&!state.present?'/choose':null;
    if(accountPath){if(accountPath!==location.pathname+location.search||location.hash)history[replace?'replaceState':'pushState'](null,'',accountPath);return;}
    if(state.client||!state.studio?.id)return;
    const globalViews=['projects','studio-users','all-activity','all-comments','profile','billing','website'];
    const view=state.settingsOpen?'settings':state.present?'slide':globalViews.includes(state.tab)?state.tab:state.data?'project':'projects';
    const path=workspaceUrl({studioId:state.studio.id,view,presentationMode:state.presentationMode,websiteEditing:!!state.websiteEditing,communicationFilter,projectId:state.data?.project.id,iteration:state.data?.iteration.id,tab:state.tab,slide:state.present?slideDefs()[state.slide]?.id:undefined,search:state.projectSearch,archived:state.showArchived});
    if(path!==location.pathname+location.search||location.hash)history[replace?'replaceState':'pushState'](null,'',path);
}
