let teamPicker={users:[],selected:new Set(),roles:{}};
async function projectTeamModal(){teamPicker={users:(await api('studio_users')).users,selected:new Set((state.data.members||[]).map(u=>u.id)),roles:Object.fromEntries((state.data.people?.team||state.data.team||[]).map(u=>[u.id,u.role||'']))};openModal(tr("studio_project_team"),`<p>${tr("studio_select_existing_studio_members_and_set_their_role_in_this_project_studio_admins_manage_member_detail")}</p><form data-form="project-team"><div id="team-selected" class="team-selected"></div><div class="team-search-panel"><label>${tr("studio_find_studio_members")}<input id="team-search" type="search" placeholder="${tr("studio_search_name_or_email")}" autocomplete="off"></label><div id="team-results" class="team-results"></div></div>${formFooter(tr("studio_save_team"))}</form>`);renderTeamPicker();}
function renderTeamPicker(){const search=($('#team-search')?.value||'').trim().toLowerCase(),selected=teamPicker.users.filter(u=>teamPicker.selected.has(u.id)),matches=teamPicker.users.filter(u=>!teamPicker.selected.has(u.id)&&(`${u.name} ${u.email}`).toLowerCase().includes(search));$('#team-selected').innerHTML=`<p>${tr("studio_team_member",{v0:selected.length,v1:selected.length===1?'':'s'})}</p><div class="team-role-list">${selected.map(u=>`<div class="team-role-row">${personAvatar(u.profile,u.name)}<div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small><label>${tr("studio_role_in_this_project")}<input data-team-role="${esc(u.id)}" value="${esc(teamPicker.roles[u.id]||'')}" maxlength="80" placeholder="${tr("studio_for_example_project_architect")}" aria-label="${tr("studio_role_for",{v5:esc(u.name)})}"></label></div>${iconBtn('close','team-remove',tr("studio_remove_from_team",{v0:u.name}),`data-id="${esc(u.id)}"`)}</div>`).join('')}</div>`;$('#team-results').innerHTML=matches.slice(0,20).map(u=>`<button type="button" class="team-result" data-action="team-add" data-id="${esc(u.id)}">${personAvatar(u.profile,u.name)}<span><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></span>${icon('plus')}</button>`).join('')+(matches.length>20?`<p class="form-hint">${tr("studio_matches_refine_your_search_to_find_more_people",{v0:matches.length})}</p>`:matches.length?'':`<p class="form-hint">${tr("studio_no_matching_members")}</p>`);}
document.addEventListener('input',e=>{if(e.target.matches('[data-team-role]'))teamPicker.roles[e.target.dataset.teamRole]=e.target.value;if(e.target.id==='team-search')renderTeamPicker();});
document.addEventListener('change',async e=>{if(e.target.id==='studio-select'){if(e.target.value==='new-studio'){e.target.value=state.studio.id;openModal(tr('studio_create_new_environment'),`<form data-form="new-studio"><p>${tr('studio_new_environment_description')}</p><label>${tr('studio_studio_name')}<input name="name" required maxlength="100" autocomplete="organization"></label>${formFooter(tr('studio_create_studio'),'plus')}</form>`);return;}try{applySession(await api('switch_studio',{studio_id:e.target.value}));await resetStudio();}catch(error){toast(error.message);}}});

function deleteProjectModal(project){
    if(state.client||state.studio?.role!=='admin'||!(project.can_edit??state.data?.can_edit))return;
    openModal(tr("studio_permanently_delete_this_project"),`<p>${tr("studio_this_removes")} <strong>${esc(project.name)}</strong>${tr("studio_every_iteration_uploaded_and_generated_file_comment_and_client_sharing_link_this_cannot_be_undone_in")}</p><p>${tr("studio_archive_the_project_instead_if_you_may_need_it_later")}</p><div class="modal-footer">${button(tr("cancel"),'close-modal','ghost')}${button(tr("studio_continue_to_final_check"),'prepare-delete-project','danger-text',`data-id="${esc(project.id)}"`)}</div>`);
}
function projectLogoFallback(){return state.studio?.has_logo?`<img class="studio-logo" src="${studioLogoUrl()}" alt="${tr("studio_studio_logo")}">`:defaultBrand();}
function projectSettingsModal(){
    const p=state.data.project;
    openModal(tr("studio_project_settings"),`<form data-form="project-settings" class="project-settings-content">
        <div class="project-settings-fields"><div><div class="settings-heading"><label for="project-language">${tr("presentation_language")}</label>${settingsHelp('project-language-help',tr('presentation_language'),tr('clients_see_this_language_unless_they_choose_their_own_in_their_profile'))}</div>${languageSelect(p.language).replace('<select ','<select id="project-language" ')}</div>
            <div class="project-visibility"><div class="settings-heading"><label class="check-label"><input type="checkbox" role="switch" name="team_only" ${p.visibility!=='public'?'checked':''} aria-describedby="visibility-description">${tr("studio_team_members_only")}</label>${settingsHelp('visibility-description',tr('studio_team_members_only'),tr('studio_only_the_project_team_can_edit',{v5:p.visibility==='public'?tr('studio_everyone_in_the_studio_can_view'):tr('studio_only_the_project_team_can_view')}))}</div></div>
        </div>
        ${settingsLogoUpload()}
        ${formFooter(tr("studio_save_settings"))}
    </form>`);
    const form=$('[data-form="project-settings"]');
    form.querySelector('[name="team_only"]').addEventListener('change',e=>{form.querySelector('#visibility-description').textContent=(e.target.checked?tr("studio_only_the_project_team_can_view"):tr("studio_everyone_in_the_studio_can_view"))+` ${tr("studio_only_the_project_team_can_edit_2")}`;});
    bindSettingsLogoUpload(form);
}
function bindSettingsLogoUpload(form){
    const zone=form.querySelector('[data-project-logo-drop]');
    form.querySelector('#project-logo-input').addEventListener('change',e=>stageProjectLogo([...e.target.files],form));
    zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});
    zone.addEventListener('dragleave',e=>{if(!zone.contains(e.relatedTarget))zone.classList.remove('dragging');});
    zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');stageProjectLogo([...e.dataTransfer.files],form);});
}
async function stageProjectLogo(files,form){
    const status=form.querySelector('[data-logo-status]'),file=files[0];if(!file)return;
    if(files.length!==1){status.textContent=tr("studio_choose_one_logo_image_at_a_time");return;}
    if(file.size>2*1024*1024){status.textContent=tr("studio_this_logo_is_too_large_choose_an_image_up_to_2_mb");return;}
    if(!['image/png','image/jpeg','image/webp'].includes(file.type)){status.textContent=tr("studio_choose_a_png_jpeg_or_webp_logo");return;}
    const pick=form._logoPick=(form._logoPick||0)+1,submit=form.querySelector('[type="submit"]');form._logoLoading=true;submit.disabled=true;status.textContent=tr("studio_preparing_logo_preview");
    try{
        const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});
        const image=new Image();image.src=url;await image.decode();if(image.naturalWidth*image.naturalHeight>12000000)throw Error(tr("choose_an_image_up_to_12_megapixels"));
        if(!form.isConnected||pick!==form._logoPick)return;
        form._logoFile=file;form._removeLogo=false;image.alt=tr(form.dataset.form==='studio-theme'?'selected_studio_logo':'studio_selected_presentation_logo');image.className='studio-logo';form.querySelector('[data-logo-preview]').replaceChildren(image);form.querySelector('[data-action="clear-project-logo"]').hidden=false;status.textContent=tr("studio_ready_to_save",{v0:file.name,v1:bytes(file.size)});
    }catch(error){if(form.isConnected&&pick===form._logoPick)status.textContent=error.message||tr("studio_this_image_could_not_be_opened_please_choose_another_logo");}
    finally{if(pick===form._logoPick){form._logoLoading=false;submit.disabled=false;}}
}
document.addEventListener('input',e=>{if(e.target.id==='project-search'){state.projectSearch=e.target.value;$('#project-grid').innerHTML=projectTiles();hydrateProjectCovers();syncWorkspaceUrl(true);}});
document.addEventListener('change',async e=>{if(e.target.id==='show-archived'){state.showArchived=e.target.checked;try{await loadProjects();$('#project-grid').innerHTML=projectTiles();hydrateProjectCovers();syncWorkspaceUrl(true);pollJobs();}catch(error){toast(error.message);}}});

const builtinSlideTitles={get intro(){return tr("welcome_home");},get changes(){return tr("what_s_new");},get budget(){return tr("the_investment");},get 'open-questions'(){return tr("open_questions");},get contacts(){return tr("your_project_team");},get summary(){return tr("everything_together");},get general(){return tr("studio_general_comment");}};
async function loadFeed(more=false){
 const comments=state.tab!=='all-activity',project=state.tab==='comments'?state.data.project.id:null,offset=more?(state.feedOffset??(state.feedItems||[]).length):0;
 const result=await api(comments?'comments_feed':'activity_feed',{offset,project_id:project,...(comments?{sort:commentView.sort,show_answered:!DEMO||commentView.showAnswered?1:0,...(!DEMO&&state.tab==='all-comments'?{filter:communicationFilter}:{})}:{})});state.feedItems=more?[...(state.feedItems||[]),...result.items]:result.items;state.feedOffset=result.next_offset??offset+result.items.length;state.feedMore=result.has_more;if(comments)state.unreadCount=result.unread_count??state.unreadCount;
}
function feedPage(projectOnly=false){
 const comments=state.tab!=='all-activity',items=state.feedItems||[];
 if(comments&&!DEMO){const subjects=commentThreads(items,{...commentView,showAnswered:true});return `<div class="section-title"><div><h1>${communication.t('Communication')}</h1><p class="muted">${tr('studio_across_projects_you_belong_to_in_this_studio')}</p></div></div><div class="comment-controls row between wrap"><div class="filter-chips" aria-label="${communication.t('Communication views')}">${[['all',communication.t('All communication')],['attention',tr('needs_attention')]].map(([key,label])=>button(label,'communication-filter','small '+(communicationFilter===key?'primary':''),`data-filter="${key}" aria-pressed="${communicationFilter===key}"`)).join('')}</div>${button(`${tr('sort')} ${commentView.sort==='newest'?tr('newest_first'):tr('oldest_first')}`,'sort-comments','small')}</div>${communicationFilter==='attention'?`<p class="muted">${communication.t('Unread messages, open questions or to dos, and pending approvals.')}</p>`:''}<div class="timeline">${subjects.map(({comment:c,replies})=>`<article class="timeline-item comment-card">${commentPreview(c)}<div class="comment-content"><small>${esc(c.project_name)} · V${c.iteration_number}</small><h3>${esc(c.thread_title||c.body.slice(0,100))}</h3>${c.thread_details?`<span class="tag outline">${communication.typeLabel(c.thread_details.type)}</span>`:''}<p>${esc((replies.at(-1)||c).body)}</p><div class="row wrap">${[c,...replies].some(m=>m.unread)?`<span class="tag">${communication.t('Unread')}</span>`:''}<span class="muted">${replies.length} ${tr('replies')}</span>${button(communication.t('Open conversation'),'comm-location','small',`data-id="${esc(c.id)}" data-project="${esc(c.project_id)}" data-iteration="${esc(c.iteration_id)}"`,'chat')}</div></div></article>`).join('')||`<p class="notice">${tr('studio_nothing_here_yet')}</p>`}</div>${state.feedMore?button(tr('studio_load_more'),'more-feed','','','down'):''}`;}
 if(!comments)return `<section class="attention-page project-activity-page"><div class="section-title"><div><h1>${tr('studio_project_activity')}</h1><p class="muted">${tr('newest_first')} · ${tr('studio_across_your_accessible_projects_in_this_studio')}</p></div></div><div class="attention-list activity-list">${items.map(item=>activityRow(item,true)).join('')||`<div class="attention-empty">${icon('history')}<h2>${tr('studio_nothing_here_yet')}</h2></div>`}</div>${state.feedMore?`<div class="attention-more">${button(tr('studio_load_more'),'more-feed','','','down')}</div>`:''}</section>`;

 return `<div class="section-title"><div><h${projectOnly?'2':'1'}>${comments?(DEMO?tr("studio_comments_2"):communication.t('Communication')):tr("studio_project_activity")}</h${projectOnly?'2':'1'}><p class="muted">${comments?tr("studio_replies_grouped_by_comment"):tr("newest_first")} · ${projectOnly?tr("studio_all_iterations_of_this_project"):comments?tr("studio_across_projects_you_belong_to_in_this_studio"):tr("studio_across_your_accessible_projects_in_this_studio")}</p></div></div>${comments?commentControls():''}<div class="timeline">${(comments?commentThreadList(items,true):items.map(item=>`<article class="timeline-item"><span class="event-icon">${icon('activity')}</span><div><small>${esc(date(item.created_at))} · ${esc(item.actor)}</small><h3>${esc(item.project_name)}</h3>${activityDetail(item)}${button(tr("studio_open_project_activity"),'activity-project','small ghost',`data-project="${esc(item.project_id)}" data-iteration="${esc(item.iteration_id||'')}"`,'arrow')}</div></article>`).join(''))||`<p class="notice">${comments&&!commentView.showAnswered?tr("no_unanswered_comments_turn_on_show_answered_to_include_completed_threads"):tr("studio_nothing_here_yet")}</p>`}</div>${state.feedMore?button(tr("studio_load_more"),'more-feed','','','down'):''}`;
}

async function openCommentSlide(data){state.tab='overview';await openProject(data.project,data.iteration);if(data.slide==='general'){if(communication.enabled()){state.tab='comments';render();}else feedbackModal();return;}state.inspectHidden=true;const defs=slideDefs(),index=defs.findIndex(s=>s.id===data.slide);if(index<0){openModal(tr("studio_source_slide_unavailable"),`<p>${tr("studio_this_slide_was_removed_from_its_iteration_its_comment_remains_in_the_comments_list")}</p>`);return;}startPresentation(index);feedbackModal();}

function personAvatar(profile={},name=''){return `<span class="avatar person-avatar">${profile?.avatar?`<img src="${esc(profile.avatar)}" alt="">`:esc(initials(profile?.name||name))}</span>`;}

function profilePage(client=false){const p=state.profile||state.user?.profile||{};return `<div class="profile-page"><h${client?'2':'1'}>${client?tr("your_preferences"):tr("user_profile")}</h${client?'2':'1'}><p class="muted">${tr("your_name_avatar_and_communication_preferences")}</p><div class="profile-avatar-editor"><form data-form="avatar">${imageUploadField('avatar',personAvatar(p,p.name))}<div class="row"><button class="button small" type="submit" disabled>${tr("save_avatar")}</button>${p.avatar?button(tr("remove_avatar"),'remove-avatar','small'):''}</div></form></div><form data-form="profile"><label>${tr("your_language")}${languageSelect(p.language)}</label><p class="form-hint">${tr("your_choice_applies_to_your_own_view_otherwise_presentations_follow_the_project_language_or_the_studio_language_if_none_is_set")}</p><label>${tr("display_name")}<input name="name" value="${esc(p.name||state.user?.name||'')}" required maxlength="100"></label><fieldset><legend>${tr("communication_preferences")}</legend><label class="check-label"><input type="checkbox" name="email_comments" ${p.email_comments!==false?'checked':''}>${tr("email_me_when_someone_else_comments_on_my_projects")}</label><label>${tr("notify_me_about")}<select name="email_mentions_only"><option value="0" ${!p.email_mentions_only?'selected':''}>${tr("all_conversation_messages")}</option><option value="1" ${p.email_mentions_only?'selected':''}>${tr("only_explicit_mentions")}</option></select></label><p class="form-hint">${tr("mentions_only_explanation")}</p></fieldset>${formFooter(tr("save_profile"))}</form></div>`;}
async function showProfile(){const r=await api('profile');state.profile=r.profile;if(state.client||state.tab==='destinations')openModal(tr("your_profile"),profilePage(true));else{state.present=false;state.tab='profile';render();}}
async function reloadProfile(){const r=await api('profile');state.profile=r.profile;if(state.client||state.tab==='destinations'){if(state.data)state.data.profile=r.profile;if(state.user)state.user.profile=r.profile;render();openModal(tr("your_profile"),profilePage(true));}else{state.user.profile=r.profile;render();}}
function commentAuthor(c){return `<div class="comment-author">${personAvatar(c.profile,c.author)}<small><strong>${esc(c.profile?.name||c.author)}</strong> · ${esc(date(c.created_at))}</small>${c.unread?`<span class="unread-badge" data-unread="${esc(c.id)}">${tr("unread")}</span>`:''}</div>`;}
function commentPreview(c){const attrs=c.project_id?`data-action="comment-slide" data-project="${esc(c.project_id)}" data-iteration="${esc(c.iteration_id)}" data-slide="${esc(c.slide)}"`:'disabled';return `<button class="comment-preview" type="button" ${attrs} aria-label="${tr("open_commented_slide")}"><img data-comment-preview="${esc(c.id)}" alt="${esc(c.slide_title||builtinSlideTitles[c.system_slide_type||c.slide]||tr("slide_preview"))}" loading="lazy"></button>`;}
async function hydrateCommentPreviews(){if(TOUR_MODE)return;for(const im of document.querySelectorAll('[data-comment-preview]')){const id=im.dataset.commentPreview,key='comment-'+id;if(im.dataset.loading)continue;im.dataset.loading='1';try{let url=imageCache.get(key);if(!url){const r=await fetch('api.php?'+new URLSearchParams({action:'comment_preview',id}),{credentials:'same-origin',headers:state.client&&im.dataset.iteration?{Authorization:'Client '+(state.data.communication?.iterations?.find(i=>i.id===im.dataset.iteration)?.share_id||state.clientShareId)}:resourceHeaders()});if(!r.ok)continue;url=URL.createObjectURL(await r.blob());imageCache.set(key,url);}im.src=url;}catch{im.alt=tr('error_slide_preview_unavailable');}}}
async function markCommentsRead(comments){const ids=comments.filter(c=>c.unread).map(c=>c.id);for(const iteration of new Set(comments.filter(c=>c.unread).map(c=>c.iteration_id))){const group=comments.filter(c=>c.unread&&c.iteration_id===iteration).map(c=>c.id);for(let n=0;n<group.length;n+=100)await api('read_comments',{iteration,ids:group.slice(n,n+100)});}if(!ids.length)return;for(const c of [...(state.data?.comments||[]),...(state.data?.communication?.comments||[]),...(state.feedItems||[])])if(ids.includes(c.id))c.unread=false;document.querySelectorAll('[data-unread]').forEach(el=>{if(ids.includes(el.dataset.unread))el.remove();});if(!state.client)state.unreadCount=(await api('session')).unread_count||0;const balloon=$('.comment-balloon');if(balloon){const all=state.data.comments.filter(c=>c.slide===slideDefs()[state.slide]?.id);balloon.innerHTML=icon('chat')+tr('comment_count',{count:all.length})+(all.some(c=>c.unread)?tr('unread_suffix'):'');}}



document.addEventListener('change',e=>{if(!e.target.matches('input[type=file]')||e.target.matches('[data-image-upload-input]')||['wizard-file-input','project-logo-input'].includes(e.target.id))return;const label=e.target.closest('label')||e.target.parentElement;label.querySelector('.upload-selection')?.remove();if(e.target.files.length){const summary=document.createElement('span');summary.className='upload-selection';summary.setAttribute('role','status');summary.textContent=[...e.target.files].map(f=>`${f.name} · ${bytes(f.size)}`).join(', ');label.append(summary);}});

document.addEventListener('change',event=>{
    const select=event.target.closest('[data-image-variant]');if(!select)return;
    const id=select.dataset.imageVariant,record=state.data.slides.find(s=>s.id===id);
    if(!record?.image_variants?.some(v=>v.id===select.value))return;
    const inLightbox=!!select.closest('#photo-lightbox');
    selectedEnhancements.set(id,select.value);showOriginalSlides.delete(id);
    render();if(magnifiedPhoto)renderPhotoLightbox();
    document.querySelector(`${inLightbox?'#photo-lightbox':'#app'} [data-image-variant="${CSS.escape(id)}"]`)?.focus({preventScroll:true});
});

setInterval(async()=>{
    if(DEMO||state.routeFailed||!state.user||state.client||!state.studio?.id||document.hidden||activeModal||state.tab==='destinations')return;
    try{const before=JSON.stringify(state.billing),wasEmpty=state.studioEmpty;await loadProjects();if(state.tab==='projects'&&wasEmpty!==state.studioEmpty)render();else if(state.data)await refresh();else if(before!==JSON.stringify(state.billing))render();}catch{/* Request-time access checks remain authoritative. */}
},60000);
